// Extract metadata for notification payload
const item = items[0].json;
return [{
  json: {
    clarificationId: item.clarificationId,
    tenderId: item.tenderId,
    bidderName: item.bidderName,
    issueCategory: item.issueCategory,
    deadline: item.responseDeadline,
    emailSubject: `CPCL GeM Clarification Notice: Tender ${item.tenderId} - ${item.issueCategory}`,
    emailBody: `Dear Authorized Bidder Representative,\n\nA statutory clarification notice has been issued for Tender ${item.tenderId} regarding '${item.issueCategory}'.\n\nPlease log in to the e-BID PRAMAAN Vendor Portal and submit your response prior to ${item.responseDeadline}.\n\nNote: Clarifications must not alter commercial bid prices.`
  }
}];
